#!/usr/bin/env python3
import json,pathlib,statistics as s
p=pathlib.Path(__file__).parent;e=p/'evidence';data=json.loads((e/'full.json').read_text());rows=data['rows'];audit=json.loads((e/'audit.json').read_text())['rows']
assert len(rows)==54 and len(audit)==18 and all(r['returncode']==0 for r in rows+audit)
lines=['# Equal-total arena policy sensitivity','', '18/18 uniform 512-call audits and 54/54 timed receipts passed. Each timed process used 100 warmups and 9 batches of 32 calls; three rotating fresh-process rounds per cell. One binary, unchanged production policy; no V8 run. All timed rows performed real collections.','', 'Production source: `2a907dab`; test-only geometry source: `d473d430`; final runner: `8291d882`. Binary SHA256: `'+data['provenance']['binary_sha256']+'`. Exact seven tags are in raw provenance. Qualification `TestGCBridgeGeometry` passed.','', 'All splits have 18 MiB usable arena plus 16-byte guard and derived/independently core-tested FixedBytes 28,463,151. Metadata includes arena alignment, start/dirty tables, mark bitmap, traversal queue and remembered queue. Excludes descriptors/Go headers/runtime roots. Equal reserved capacity is not equal committed RSS.','', '| Case | Young/each-old MiB | median process ms | ratio of medians | within-round ratios | timed Minor/Full | process HWM KiB |','|---|---|---:|---:|---|---|---|']
for case in dict.fromkeys(r['case'] for r in rows):
 groups={v:[r for r in rows if r['case']==case and r['variant']==v] for v in ['young2-old8','young4-old7','young6-old6']}
 baseline=[s.median(r['result']['samples_ns']) for r in groups['young2-old8']]
 for v,rs in groups.items():
  ns=[s.median(r['result']['samples_ns']) for r in rs];ratios=[x/y for x,y in zip(ns,baseline)];cnt=[(r['result']['after']['MinorCollections']-r['result']['before']['MinorCollections'],r['result']['after']['FullCollections']-r['result']['before']['FullCollections']) for r in rs];assert len(set(cnt))==1
  alloc=[r['result']['after']['Allocations']-r['result']['before']['Allocations'] for r in rs];assert len(set(alloc))==1 and alloc[0]==groups['young2-old8'][0]['result']['after']['Allocations']-groups['young2-old8'][0]['result']['before']['Allocations']
  lines.append('|'+case+'|'+v+'|'+f'{s.median(ns)/1e6:.4f}|{s.median(ns)/s.median(baseline):.3f}|' + ', '.join(f'{x:.3f}' for x in ratios)+f'|{cnt[0][0]}/{cnt[0][1]}|'+', '.join(str(r['result']['proc_VmHWM_kib']) for r in rs)+'|')
lines += ['', '## Interpretation', '', 'Larger nurseries consistently reduced Minor/Full frequency on these graphs. Array allocation, fill and tree were faster in every paired round at both larger splits. This is actionable policy sensitivity, not a general collector speedup or proof of the V8 target. Six-MiB nursery struct was also faster in every round, but the first baseline process was a conspicuous outlier; four-MiB struct was slower in two of three rounds. Copy/loopcopy results are mixed and variable; six-MiB copy ratio-of-medians 1.462 is not a stable per-round 46% regression (ratios 1.044, 0.977, 1.536). Do not select a universal default from these results.', '', 'Copy workloads show committed-memory tradeoff despite identical reserved bytes: process high-water RSS rises roughly 18,800–19,100 KiB to 23,400–23,700 KiB. Larger nursery touches more pages before collection. Reducing each old space 8→7→6 MiB also reduces maximum old live-set capacity; these six small-live-set graphs do not bound that risk. Validate a retained-old graph near 6–8 MiB before any default change.', '', 'All rows preserve exact checksums/artifact hashes and allocation counts; counters deterministic across rounds. Copied/promoted byte zeros remain uninstrumented, not evidence of no work. Process-level replications, not 27 pooled batch samples, underpin comparisons. Own local workers paused; processes unpinned; external host contention/cache/scheduling drift cannot be excluded.', '', '## Preserved failed attempts', '', '1. Initial runner iterated entire corpus manifest. After 9 intended audits passed, non-heap i31-roundtrip failed `collector selection mismatch`. Scope corrected to six intended GC workloads. This was not a heap semantic failure.', '2. Complete corrected audit restarted with 128 calls. After 10 passed rows, young 4/old 7 copy failed `probe completed without any real collection; increase warmup`. Uniform 512-call audits then restarted from scratch. Final timed protocol unchanged; no rows spliced and no guards relaxed.', '', '## Next validation', '', 'Repeat adjacent reversed-order pairs for array allocation/fill/tree and disputed copy/struct, using all splits and sufficiently long uniform batches. Add a controlled old-live-set pressure audit to quantify capacity loss. Any V8 comparison requires a fresh contemporaneous unchanged-artifact gate and still cannot claim matched V8 heap policy. No production promotion recommended yet.']
(e/'summary.md').write_text('\n'.join(lines)+'\n')
